"""Render recorded runs as a markdown table.

Generated rather than hand-written. The previous version of this document was
prose I typed, with nothing stopping it drifting from what the runs actually
produced -- the same class of problem as an eval dataset contaminating its own
measurement.
"""

from __future__ import annotations

from pathlib import Path

from workspace_indexer.evaluation.eval_record import EvalRecord

DEFAULT_REPORT_PATH = Path("docs/eval-baselines.md")

_HEADER = """# Eval baselines

<!-- Generated by `workspace-indexer eval`. Do not edit by hand: it is
     rewritten on every recorded run, and anything added here is lost. -->

Every recorded run, newest first. Two runs are only comparable when the
configuration hash, fusion mode, reranker, tool and case group all match --
those are the columns to check before reading a delta as a result. A
find_guidance run over the eight guidance cases and a plain search run over all
sixteen are both honest numbers, and comparing them is meaningless.

Query text is deliberately omitted. A document quoting the eval queries becomes
a perfect match for them, which puts it at the top of its own results; the full
per-case detail lives in `evals/*.json`.
"""

# `tool` and `cases` are columns rather than a footnote because without them
# three rows can share a configuration, differ by 0.15 MRR, and look like a
# regression. They are what the numbers were measured *over*.
_COLUMNS = (
    "| recorded | embedding | dims | fusion | reranker | tool | cases "
    "| recall@k | MRR@k | misses |\n"
    "|---|---|---|---|---|---|---|---|---|---|\n"
)


# Appended to every regeneration. Documentation about the data belongs with
# the data -- appending it by hand would be wiped on the next run, which is
# what the header above warns about and what I did anyway the first time.
_FOOTER = """
## Ad hoc analysis

The run files are plain JSON, so DuckDB can query them directly. It is not a
project dependency: install it when you want it, or use its own CLI.

```sql
-- every run, newest first
SELECT recorded_at, embedding_model, dimensions, reranker, recall_at_k, mrr_at_k
FROM read_json_auto('evals/*.json')
ORDER BY recorded_at DESC;

-- queries that have never been answered well, across every run
SELECT r.query,
       count(*) AS runs,
       sum(CASE WHEN r.first_hit_rank IS NULL THEN 1 ELSE 0 END) AS misses
FROM read_json_auto('evals/*.json') AS e, UNNEST(e.results) AS t(r)
GROUP BY r.query
HAVING misses > 0
ORDER BY misses DESC;
```

Parquet was considered and rejected: it is binary, which would destroy the
diffability that is the main reason for choosing files at all, and its
advantages appear at millions of rows rather than the few thousand here.
"""


def render(records: list[EvalRecord]) -> str:
    rows = "".join(
        f"| {r.recorded_at[:19]} "
        f"| `{r.embedding_model}` "
        f"| {r.dimensions} "
        f"| {r.fusion} "
        f"| `{r.reranker}` "
        f"| {r.retriever} "
        f"| {r.case_filter} "
        f"| {r.recall_at_k:.3f} "
        f"| {r.mrr_at_k:.3f} "
        f"| {r.miss_count}/{r.case_count} |\n"
        for r in sorted(records, key=lambda r: r.recorded_at, reverse=True)
    )
    body = _COLUMNS + rows if records else "_No runs recorded yet._\n"
    return f"{_HEADER}\n{body}{_FOOTER}"


def write_report(records: list[EvalRecord], path: Path = DEFAULT_REPORT_PATH) -> Path:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(render(records), encoding="utf-8")
    return path
